import React from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods, useThoughts } from '../hooks/useStorage';

const TRAP_SHORT = {'Katastrofiering':'KATASTR.','Tankeläsning':'TANKELÄS.','Svartvitt tänkande':'SVART/VIT','Övergeneralisering':'ÖVERGENER.','Känslomässigt resonerande':'KÄNSLO.','Personalisering':'PERSONAL.','Filtrerande':'FILTR.','Bör-tänkande':'BÖR-TÄNK.'};
const MOOD_COLORS = {1:'#e05050',2:'#d07840',3:'#c8b040',4:'#50a870',5:'#5090d0'};

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const isEmpty = moods.length===0 && thoughts.length===0;
  const maxTrap = Math.max(...Object.values(trapCounts),1);
  const avgEmoji = ['','😔','😟','😐','🙂','😄'];

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px', position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 50% 40%, rgba(50,50,80,0.14) 0%, transparent 55%)', pointerEvents:'none' }} />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={220} speed={0.3} distort={0.5} />
        </div>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:10 }}>Historik · 0 poster</div>
        <h2 style={{ fontSize:32, fontWeight:900, letterSpacing:'-0.04em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:22 }}>Tom historik</h2>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('home')} style={{ padding:'12px 22px', borderRadius:12, background:'rgba(242,240,235,0.95)', color:'#0c0c0e', fontSize:11, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', boxShadow:'0 4px 20px rgba(0,0,0,0.4)' }}>Analysera</button>
          <button onClick={()=>setPage('checkin')} className="liq" style={{ padding:'12px 22px', borderRadius:12, color:'rgba(242,240,235,0.55)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Check-in</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'radial-gradient(circle at 70% 15%, rgba(60,40,80,0.12) 0%, transparent 45%)', pointerEvents:'none' }} />

      <div style={{ padding:'24px 16px', position:'relative', zIndex:1 }}>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:6 }}>Din historik</div>
        <h1 style={{ fontSize:'clamp(36px,9vw,56px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.86, textTransform:'uppercase', color:'#f2f0eb', marginBottom:24 }}>
          DATA<br/><span style={{ color:'rgba(242,240,235,0.16)' }}>LOGG</span>
        </h1>

        {/* Stats — liquid glass grid */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:8, marginBottom:12 }}>
          {[
            { val:streak, label:'Streak',   suf:'dgr' },
            { val:thoughts.length, label:'Analyser', suf:'' },
            { val:avgMood>0?avgMood:'—', label:'Snitt', suf:'' },
          ].map(({val,label,suf})=>(
            <div key={label} className="liq" style={{ padding:'14px 10px', textAlign:'center', borderRadius:16 }}>
              <div style={{ fontSize:24, fontWeight:900, letterSpacing:'-0.04em', color:'#f2f0eb', lineHeight:1 }}>{val}<span style={{ fontSize:11, color:'rgba(242,240,235,0.3)', fontWeight:400, marginLeft:2 }}>{suf}</span></div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:7, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginTop:5 }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Mood chart */}
        {moods.length>0 && (
          <div className="liq" style={{ padding:'16px 18px', marginBottom:10, borderRadius:18 }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:14 }}>Humör · Trend</div>
            <div style={{ display:'flex', alignItems:'flex-end', gap:3, height:60 }}>
              {[...moods].reverse().map((m,i)=>(
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2, height:'100%', justifyContent:'flex-end' }}>
                  <div style={{ width:'100%', background:MOOD_COLORS[m.score], height:`${(m.score/5)*100}%`, minHeight:3, borderRadius:'3px 3px 0 0', boxShadow:`0 0 10px ${MOOD_COLORS[m.score]}44` }} />
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:6, color:'rgba(242,240,235,0.2)', whiteSpace:'nowrap' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trap freq */}
        {Object.keys(trapCounts).length>0 && (
          <div className="liq" style={{ padding:'16px 18px', marginBottom:10, borderRadius:18 }}>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:14 }}>Tankefällor · Frekvens</div>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).map(([label,count])=>(
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(242,240,235,0.38)', width:68, flexShrink:0, letterSpacing:'0.06em' }}>{TRAP_SHORT[label]||label.slice(0,8).toUpperCase()}</div>
                <div style={{ flex:1, height:2, background:'rgba(255,255,255,0.07)', borderRadius:2 }}>
                  <div style={{ height:'100%', borderRadius:2, background:'rgba(242,240,235,0.45)', width:`${(count/maxTrap)*100}%`, boxShadow:'0 0 6px rgba(242,240,235,0.15)', transition:'width .8s cubic-bezier(0.16,1,0.3,1)' }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.28)', width:14, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought log */}
        {thoughts.length>0 && (
          <>
            <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', margin:'18px 0 8px' }}>Log · Analyser</div>
            {thoughts.map(th=>(
              <div key={th.id} className="liq" style={{ marginBottom:8, padding:'14px 18px', borderRadius:16, position:'relative', overflow:'hidden' }}>
                <div style={{ position:'absolute', top:0, left:0, bottom:0, width:2, background:'rgba(255,255,255,0.12)', borderRadius:'2px 0 0 2px' }} />
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:7, paddingLeft:10 }}>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.1em', textTransform:'uppercase', color:'rgba(242,240,235,0.45)' }}>{th.trap_icon||'▸'} {th.trap_label}</span>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:8, color:'rgba(242,240,235,0.2)' }}>{new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span>
                </div>
                <p style={{ fontSize:12, color:'rgba(242,240,235,0.3)', fontStyle:'italic', marginBottom:8, lineHeight:1.6, paddingLeft:10 }}>"{th.user_text?.slice(0,90)}{th.user_text?.length>90?'...':''}"</p>
                <p style={{ fontSize:12, color:'rgba(242,240,235,0.62)', lineHeight:1.7, fontWeight:300, paddingLeft:10 }}>{th.reframe}</p>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
